// Minimal GSAP stub to prevent errors when CDN is unavailable
(function(global){
  if (global.gsap) return;
  function select(target){
    if (typeof target === 'string') return document.querySelector(target);
    return target;
  }
  var gsap = {
    to: function(target, vars){
      var el = select(target);
      if (!el || !vars) return;
      var duration = vars.duration || 0;
      var delay = vars.delay || 0;
      var props = Object.assign({}, vars);
      delete props.duration;
      delete props.delay;
      setTimeout(function(){
        Object.keys(props).forEach(function(k){
          try {
            if (k in el.style) {
              el.style[k] = props[k];
            }
          } catch (e) {}
        });
      }, delay * 1000);
    }
  };
  global.gsap = gsap;
})(window);